export type Endpoint = {
    /**
     * Server-enforced recipient for an address-scoped pull subscription; null for an account-wide destination created before pull creation required a connected-agent credential.
     */
    recipient?: string | null;
    receiver_capabilities?: {
        completion_modes: Array<'http' | 'exec' | 'stdout' | 'sdk'>;
        stream_protocols: Array<'primitive.events.v1'>;
    };
    id: string;
    org_id: string;
    url?: string | null;
    enabled: boolean;
    /**
     * Restrict this endpoint to emails from a specific domain
     */
    domain_id?: string | null;
    /**
     * Endpoint-specific filtering rules
     */
    rules: {
        /**
         * Event types this endpoint receives. Omitted: every event type except the opt-in sent_email.* events, which an endpoint receives only when it lists them.
         */
        event_types?: Array<string>;
        /**
         * Skip messages larger than this many bytes.
         */
        max_size_bytes?: number;
        /**
         * When true, skip messages that have attachments.
         */
        exclude_attachments?: boolean;
        /**
         * Skip messages whose attachments total more than this many megabytes.
         */
        attachment_limit_mb?: number;
        /**
         * Deliver only messages whose authenticated From identity matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_whitelist?: Array<string>;
        /**
         * Skip messages whose envelope sender or From address matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_blacklist?: Array<string>;
        [key: string]: unknown;
    };
    created_at: string;
    updated_at: string;
    /**
     * Total webhook deliveries attempted
     */
    delivery_count: number;
    /**
     * Successful deliveries
     */
    success_count: number;
    /**
     * Failed deliveries
     */
    failure_count: number;
    /**
     * Current streak of consecutive failures
     */
    consecutive_fails: number;
    last_delivery_at?: string | null;
    last_success_at?: string | null;
    last_failure_at?: string | null;
    deactivated_at?: string | null;
    /**
     * http: deliver to the webhook URL. function: invoke a Primitive Function.
     */
    kind?: 'http' | 'function' | 'pull';
    /**
     * The Function this endpoint invokes, when kind is function.
     */
    function_id?: string | null;
    /**
     * When true, this endpoint is reachable only via an explicit recipient
     * route, never as a domain's default destination, and is exempt from
     * the one-endpoint-per-domain rule (so many can share a domain).
     *
     */
    is_route_target?: boolean;
    /**
     * Stable name of a pull destination.
     */
    name?: string | null;
    /**
     * Whether an API key owns this webhook instead of the organization.
     */
    owned_by_key?: boolean;
    /**
     * The API key that owns this webhook. In endpoint responses it is set only for a caller who may read API key metadata, and is null otherwise and when the organization owns the webhook. After a rotation, the key that carries on for the key first named while it can act.
     */
    owner_key_id?: string | null;
    /**
     * Whether the owning key can act now. In endpoint responses it is set only for a caller who may read API key metadata. Suspended also covers an expired key. A suspended or revoked owner is sent nothing.
     */
    owner_key_status?: 'active' | 'suspended' | 'revoked' | null;
};

export type CreateEndpointInput = {
    /**
     * http: deliver to url. function: invoke function_id. pull: receive locally using a stable name, without a URL.
     */
    kind?: 'http' | 'function' | 'pull';
    /**
     * The webhook URL to deliver events to. Required when kind is http; omit for function endpoints.
     */
    url?: string;
    /**
     * The Function to invoke. Required when kind is function.
     */
    function_id?: string;
    /**
     * Whether the endpoint is active
     */
    enabled?: boolean;
    /**
     * Restrict to emails from a specific domain
     */
    domain_id?: string | null;
    /**
     * Endpoint-specific filtering rules
     */
    rules?: {
        /**
         * Event types this endpoint receives. Omitted: every event type except the opt-in sent_email.* events, which an endpoint receives only when it lists them.
         */
        event_types?: Array<string>;
        /**
         * Skip messages larger than this many bytes.
         */
        max_size_bytes?: number;
        /**
         * When true, skip messages that have attachments.
         */
        exclude_attachments?: boolean;
        /**
         * Skip messages whose attachments total more than this many megabytes.
         */
        attachment_limit_mb?: number;
        /**
         * Deliver only messages whose authenticated From identity matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_whitelist?: Array<string>;
        /**
         * Skip messages whose envelope sender or From address matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_blacklist?: Array<string>;
        [key: string]: unknown;
    };
    /**
     * Create this endpoint as a route-target: reachable only via an
     * explicit recipient route, never a domain's default destination, and
     * exempt from the one-endpoint-per-domain rule.
     *
     */
    is_route_target?: boolean;
    /**
     * Stable name within the credential scope, required for kind=pull. Only connected-agent credentials can create pull destinations, and each receives only its assigned address.
     */
    name?: string;
    /**
     * When the domain (or, with no domain_id, the organization's fallback slot) already has an active endpoint: false (the default) answers 409 conflict with details.holder naming it; true retires that endpoint in the same request, after the checks deleting it would need. Route targets and pull destinations never hold the slot. A plan limit (one fallback webhook on the free plan, Power for per-domain webhooks) is checked first, and takeover lifts only the fallback limit the holder itself would count against.
     */
    takeover?: boolean;
    /**
     * Make this webhook owned by an API key of the organization instead of by the organization. It receives the mail recipient routes send to it and interaction events for addresses the key reads, each checked against the key: only mail the key can read is sent, and nothing while the key is revoked or suspended. It is never a domain or organization default: it is created as a route target, and is_route_target false or takeover is refused. Not a connected agent key or a Function key.
     */
    owner_key_id?: string;
};

export type UpdateEndpointInput = {
    /**
     * New webhook URL (triggers endpoint rotation)
     */
    url?: string;
    enabled?: boolean;
    domain_id?: string | null;
    rules?: {
        /**
         * Event types this endpoint receives. Omitted: every event type except the opt-in sent_email.* events, which an endpoint receives only when it lists them.
         */
        event_types?: Array<string>;
        /**
         * Skip messages larger than this many bytes.
         */
        max_size_bytes?: number;
        /**
         * When true, skip messages that have attachments.
         */
        exclude_attachments?: boolean;
        /**
         * Skip messages whose attachments total more than this many megabytes.
         */
        attachment_limit_mb?: number;
        /**
         * Deliver only messages whose authenticated From identity matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_whitelist?: Array<string>;
        /**
         * Skip messages whose envelope sender or From address matches an entry: an exact address, or @domain, which also matches its subdomains.
         */
        sender_blacklist?: Array<string>;
        [key: string]: unknown;
    };
    /**
     * For a move to another domain_id whose slot already has an active endpoint: false (the default) answers 409 conflict with details.holder naming it; true retires that endpoint in the same request, after the checks deleting it would need.
     */
    takeover?: boolean;
    /**
     * Give this webhook to an API key of the organization. Only a route target can be given to a key; a default endpoint stays the organization's, and takeover is refused with it. null gives a key-owned webhook back to the organization (a caller with access to every mailbox only); it stays a route target.
     */
    owner_key_id?: string | null;
};

export type TestResult = {
    /**
     * HTTP status code returned by the endpoint
     */
    status: number;
    /**
     * Response body (truncated to 1000 characters)
     */
    body: string;
    /**
     * The signature header value sent (if webhook secret is configured)
     */
    signature?: string;
};

export type TestEndpointRulesInput = {
    /**
     * Id of an already-received email (in your org) to evaluate the rules against.
     */
    email_id: string;
};

/**
 * Verdict of a dry-run rule evaluation. Produced by the same
 * shared matcher the live delivery paths use.
 *
 */
export type TestEndpointRulesResult = {
    /**
     * Whether the delivery path would deliver this email to the endpoint.
     */
    would_deliver: boolean;
    /**
     * Name of the failing rule when delivery would be
     * suppressed; null when the message matches and the
     * endpoint is subscribed to the event type.
     *
     */
    rule: string | null;
    /**
     * Human-readable explanation of the failing rule; null when the message matches.
     */
    reason: string | null;
    /**
     * False when the endpoint's stored rules blob failed
     * validation. Delivery fails OPEN on an invalid blob
     * (delivers as if unfiltered), so false here surfaces a
     * misconfiguration that is otherwise silent.
     *
     */
    rules_valid: boolean;
    /**
     * Whether the endpoint's event-type subscription includes
     * this email's event type. A separate gate applied before
     * message matching, surfaced independently so an
     * unsubscribed endpoint is distinguishable from a rule
     * rejection.
     *
     */
    subscribed_to_event: boolean;
    /**
     * The event type this email would be delivered as.
     */
    event_type: string;
    /**
     * The message metadata the matcher compared, so the caller
     * can see WHAT was evaluated (in particular the
     * authenticated From identity versus the raw envelope
     * sender).
     *
     */
    evaluated: {
        size_bytes: number;
        has_attachments: boolean;
        attachment_size_bytes: number;
        /**
         * Raw envelope sender the blacklist matches against.
         */
        sender: string;
        /**
         * Bare From-header address, when one was present.
         */
        from_address: string | null;
        /**
         * Whether the sender identity passed authentication (the whitelist matches only authenticated identities).
         */
        sender_authenticated: boolean;
        /**
         * Which signal established (or failed to establish) the sender identity.
         */
        sender_trust_basis: string;
    };
};

