        explanation: string;
        assumptions: Array<string>;
        warnings: Array<string>;
        /**
         * Who produced the tree, as the caller stated it when saving (not verified), for example rule-compiler-v1 or member.
         */
        compiled_by: string;
        vocabulary: string;
